use std::{collections::HashMap, fs, path::PathBuf};

/// Checks that the programs assembled by the `pipeline` module match the
/// reference encodings generated by `pioasm`.
///
/// `pico-examples.rs` runs the same comparison for the legacy parser.
#[test_generator::test_resources("tests/pico-examples/*.pio")]
fn pipeline_matches_pioasm(test: &str) {
    // rmii_rx.pio uses `wait jmppin`, an RP2350-only instruction which the
    // pipeline does not support yet.
    if test.ends_with("rmii_rx.pio") {
        return;
    }

    let path = PathBuf::from(test);
    let program_source = fs::read_to_string(&path).unwrap();

    let file = pio_parser::pipeline::compile_and_assemble::<{ pio::RP2040_MAX_PROGRAM_SIZE }>(
        &program_source,
    )
    .unwrap_or_else(|e| panic!("{test}: assembling failed: {e:?}"));

    let mut hex_path = path;
    hex_path.set_extension("hex");
    let hex_source = fs::read_to_string(&hex_path)
        .unwrap_or_else(|e| panic!("{}: cannot read reference hex: {e}", hex_path.display()));

    let mut hex_programs: HashMap<String, Vec<u16>> = HashMap::new();
    let mut current_program = String::new();
    for line in hex_source.lines() {
        if let Some(new_program) = line.strip_prefix(".program ") {
            current_program = new_program.into();
            hex_programs.insert(current_program.clone(), vec![]);
        } else {
            hex_programs
                .get_mut(&current_program)
                .unwrap()
                .push(u16::from_str_radix(line, 16).unwrap());
        }
    }

    for (name, expected) in hex_programs.iter() {
        let assembled = file
            .programs
            .get(name.as_str())
            .unwrap_or_else(|| panic!("{test}: no program named `{name}`"));
        assert_eq!(&*assembled.program.program.code, expected, "{test}: {name}");
    }
}
